function validate([arr]) {
  if (arr.length < 1 || arr.length > 500) return 'arr needs 1 to 500 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 500)) return 'Each value is an integer from 1 to 500.';
  return null;
}

