function findLucky(arr) {
  const count = new Array(501).fill(0);
  for (const value of arr) {
    count[value]++;
  }
  for (let value = arr.length; value >= 1; value--) {
    if (count[value] === value) {
      return value;
    }
  }
  return -1;
}

