function findLucky(arr) {
  // For every element, count its copies by scanning the whole array again.
  let best = -1;
  for (const candidate of arr) {
    const copies = arr.filter(v => v === candidate).length;
    if (copies === candidate && candidate > best) best = candidate;
  }
  return best;
}

