function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 500 : 1 + pick(12);
  const top = size === 'large' ? (rand() < 0.5 ? 500 : 40) : 1 + pick(6);
  const arr = [];
  // Plant a few runs of v copies of v so that lucky integers are common.
  while (arr.length < n && rand() < 0.7) {
    const v = 1 + pick(Math.min(top, n - arr.length));
    for (let i = 0; i < v; i++) arr.push(v);
  }
  while (arr.length < n) arr.push(1 + pick(top));
  for (let i = arr.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return [arr];
}
